// Copies the rendered bible from design-bible/ into public/chapters/, where the
// reader fetches it from (chapters/00.md … chapters/18.md, chapters/sources.md).
//
// The chapters are generated by design-bible/build_bible.py and committed there,
// once. This keeps it that way: public/chapters/ is gitignored and rebuilt from
// design-bible/ before every `vite` and `vite build` (the package's scripts chain
// it), and the copy that ships is the one that lands in the committed dist/.
//
//   design-bible/NN-<name>.md → public/chapters/NN.md
//   design-bible/sources.md   → public/chapters/sources.md

import { copyFile, mkdir, readdir, rm } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const pkgDir = dirname(dirname(fileURLToPath(import.meta.url)))
const bibleDir = join(pkgDir, '..', '..', 'design-bible')
const outDir = join(pkgDir, 'public', 'chapters')

const CHAPTER = /^(\d\d)-[a-z0-9-]+\.md$/
const EXPECTED = 19 // 00 … 18; the reader's table of contents is hard-coded to these

const pairs = []
for (const name of (await readdir(bibleDir)).sort()) {
  const m = CHAPTER.exec(name)
  if (m) pairs.push([name, `${m[1]}.md`])
}
pairs.push(['sources.md', 'sources.md'])

const numbers = pairs.slice(0, -1).map(([, out]) => out)
if (numbers.length !== EXPECTED || new Set(numbers).size !== EXPECTED) {
  throw new Error(`Expected ${EXPECTED} chapters 00-18 in ${bibleDir}, found: ${numbers.join(', ') || 'none'}`)
}

// Start clean so a renamed or removed chapter can't linger in the build.
await rm(outDir, { recursive: true, force: true })
await mkdir(outDir, { recursive: true })
for (const [from, to] of pairs) await copyFile(join(bibleDir, from), join(outDir, to))

console.log(`copied ${pairs.length} files from design-bible/ → public/chapters/`)
